run_query_body:
let mut c: u64 = 0;
let mut i: usize = t.n;
while i > 0
    invariant
        i <= t.n,
        valid_cols_t(t),
        c as int == count_distinct_c(t, i as int),
        c as int <= (t.n - i) as int,
    decreases i,
{
    i = i - 1;
    let a = t.a[i];
    let mut dup: bool = false;
    let mut j: usize = i + 1;
    while j < t.n
        invariant
            i < j <= t.n,
            valid_cols_t(t),
            t.a@[i as int] == a,
            dup <==> exists|j0: int| (i as int) < j0 && j0 < (j as int) && t.a@[j0] == a,
        decreases t.n - j,
    {
        if t.a[j] == a {
            dup = true;
        }
        j = j + 1;
    }
    proof {
        lemma_count_distinct_c_step(t, i as int);
        assert(j == t.n);
        let ii = i as int;
        if dup {
            let j0 = choose|j0: int| ii < j0 && j0 < (j as int) && t.a@[j0] == a;
            assert(row_hit(t, j0));
            assert(count_distinct_c_val(t, j0) == count_distinct_c_val(t, ii));
        }
        if exists|j0: int| (j0 > ii) && row_hit(t, j0) && count_distinct_c_val(t, j0) == count_distinct_c_val(t, ii) {
            let j0 = choose|j0: int| (j0 > ii) && row_hit(t, j0) && count_distinct_c_val(t, j0) == count_distinct_c_val(t, ii);
            assert(t.a@[j0] == a);
            assert(dup);
        }
    }
    if !dup {
        c = c + 1;
    }
}
let mut res: Vec<OutRow> = Vec::new();
res.push(OutRow { c: c });
res
